/**
 * El Regista icons, drawn with the same stroke system as the Regista Display
 * typeface (generated by scripts/brand/build_icons.py; do not edit by hand).
 */

type IconProps = {
  size?: number;
  className?: string;
  color?: string;
};

function Icon({ d, size = 20, className, color = "currentColor" }: IconProps & { d: string }) {
  return (
    <svg width={size} height={size} viewBox="-4 -4 108 108" className={className} aria-hidden="true">
      <path d={d} fill={color} fillRule="evenodd" />
    </svg>
  );
}

